import fs from 'node:fs';
import assert from 'node:assert/strict';
import net from 'node:net';
import {spawn,execFileSync} from 'node:child_process';
import {hash,json} from './bounded-source-hash-20261026.mjs';
const base='F:/VisibleMedicine/staging/20261027-find-keyboard-native';
const dir=base+'/browser';
const sourceFile=base+'/SOURCE_CANDIDATE.json';
assert.equal(hash(sourceFile),json(base+'/BUILD_VERIFIED.json').source.sha256);
const source=json(sourceFile),site=source.atlas;
assert(json(base+'/BUILD_VERIFIED.json').fullNativeBuildPassed);
const build=json(base+'/BUILD_VERIFIED.json');assert(build.passing);assert.equal(hash(build.artifacts.path),build.artifacts.sha256);
for(const r of [...source.sourceRows,...source.publicRows,...json(build.artifacts.path).files])assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
for(const [repo,head]of [[site,source.head],['F:/VisibleMedicine/atlas','6d7a356ae949e13f2ff4bf1fec610ee6ae7762c1'],['F:/VisibleMedicine/website','b953ff3f5f1891599cb6e91cb91311d9d6006270']])assert.equal(execFileSync('git',['-C',repo,'rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),head);
for(const p of ['.env','.env.local','.env.production','.dev.vars','.dev.vars.local'])assert(!fs.existsSync(site+'/'+p),'No owner credentials in isolated native preview');
const config=json(site+'/dist/server/wrangler.json');assert.equal(config.main,'index.js');assert(config.no_bundle);assert(!config.ai);assert(!config.services?.length);assert(![...(config.d1_databases??[]),...(config.r2_buckets??[])].some(b=>b.remote));
for(const port of [3094,49394])await new Promise((resolve,reject)=>{const s=net.createServer();s.once('error',reject);s.listen(port,'127.0.0.1',()=>s.close(resolve));});
fs.mkdirSync(dir,{recursive:true});
const save=(name,value)=>fs.writeFileSync(dir+'/'+name,JSON.stringify(value,null,2)+'\n',{flag:'wx'});
const cli=site+'/node_modules/wrangler/bin/wrangler.js';
const args=['--max-old-space-size=768',cli,'dev','--config',site+'/dist/server/wrangler.json','--local','--no-bundle','--ip','127.0.0.1','--port','3094','--inspector-ip','127.0.0.1','--inspector-port','49394','--persist-to',dir+'/local-state','--live-reload=false','--show-interactive-dev-session=false','--types=false','--log-level','warn'];
const child=spawn(process.execPath,args,{cwd:site,env:{...process.env,WRANGLER_SEND_METRICS:'false',WRANGLER_WRITE_LOGS:'false'},windowsHide:true,shell:false,stdio:['ignore','inherit','inherit']});
save('HANDLE.json',{at:new Date().toISOString(),pid:child.pid,parentPid:process.pid,url:'http://127.0.0.1:3094',args,source:{path:sourceFile,sha256:hash(sourceFile)},build:{path:base+'/BUILD_VERIFIED.json',sha256:hash(base+'/BUILD_VERIFIED.json')},stockNativeApp:true,websiteAuthenticationAcceptance:false,privateStateCopied:false,ownerPreviewChanged:false});
console.log(JSON.stringify({url:'http://127.0.0.1:3094',pid:child.pid}));
let stopping=false;const poll=setInterval(()=>{if(!stopping&&fs.existsSync(dir+'/STOP')){stopping=true;child.kill();}},500);
const terminal=await new Promise(resolve=>{child.once('error',e=>resolve({error:String(e)}));child.once('close',(code,signal)=>resolve({code,signal}));});clearInterval(poll);save('TERMINAL.json',{at:new Date().toISOString(),requestedStop:stopping,...terminal});if(!stopping)process.exitCode=1;
